"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class STACK:
    def __init__(self):
        self.array = []
        self.top = (-1)

    def PUSH(self, element):
        self.top = (self.top + 1)
        self.array[self.top] = element

    def POP(self):
        if (self.top == (-1)):
            return None
        element = self.array[self.top]
        self.top = (self.top - 1)
        return element

    def PEEK(self):
        if (self.top == (-1)):
            return None
        return self.array[self.top]
